import logging
import re
from base64 import b64encode
from typing import Union

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.devices.http_client import HttpPdu
from taf.hw.pdu.exceptions import BadDeviceStatus


class DigiPower(HttpPdu):
    _GET_STATUS_OFF = "0"
    _GET_STATUS_ON = "1"

    def __init__(
            self,
            host: str,
            login: str,
            password: str,
            timeout: Union[float, int] = 20,
            **kwargs
    ) -> None:
        super().__init__(host, timeout)
        credentials = b64encode(f"{login}:{password}".encode()).decode()
        self.headers = {"Authorization": "Basic " + credentials}
        self.status_url = "http://" + host + "/status.xml"
        self.host = host
        self._max_ports = 8
        self._http_proxy = (
            {"http": kwargs.get("http_proxy")} if kwargs.get("http_proxy") else None
        )

    def power_off(self, port):
        response = self.set_pdu(port, "off")
        expected_response = "Success"
        if expected_response not in response:
            raise RuntimeError(
                f"Unexpected response from device. Expected {expected_response}, found {response}"
            )

    def power_on(self, port):
        response = self.set_pdu(port, "on")
        expected_response = "Success"
        if expected_response not in response:
            raise RuntimeError(
                f"Unexpected response from device. Expected {expected_response}, found {response}"
            )

    def set_pdu(self, port, label):
        port = "1".rjust(port, "0")
        port = port.ljust(self._max_ports, "0")
        request = self._build_request_url(port=port, label=label)
        response = self._send_request(request)
        response = response.text
        return response

    def _send_request(self, url, method="POST", headers=None, data=None, params=None):
        if headers is None:
            headers = self.headers
        return super(DigiPower, self)._send_request(
            url=url,
            method=method,
            headers=headers,
            data=data,
            params=params,
            proxies=self._http_proxy,
        )

    def _build_request_url(self, port, label):
        if label:
            return f"http://{self.host}/{label}s.cgi?led={port}0000000000000000"
        return self.status_url

    def _get_outlet_info(self, response, port):
        regex = r"\<pot\d\>(.*)\<\/pot\d\>"
        status_raw_values = re.search(regex, response.text)
        statuses = []
        if status_raw_values:
            statuses_values = status_raw_values.group(1)
            statuses_values = statuses_values.split(",")[9 : self._max_ports + 10]
            statuses_values = [
                float(statuses_value) if statuses_value else ""
                for statuses_value in statuses_values
            ]
            statuses_values = statuses_values[1 : self._max_ports + 2]
            for status_value in statuses_values:
                if isinstance(status_value, float):
                    if status_value == 1.0:
                        statuses.append("ON")
                    elif status_value == 0.0:
                        statuses.append("OFF")
        return {"State": statuses[port - 1]}

    def _parse_response(self, response, port):
        """Parse HTTP GET/POST response from PDU server."""
        response = self._get_outlet_info(response, port)
        if response["State"] == "ON":
            return "1"
        elif response["State"] == "OFF":
            return "0"
        else:
            logging.critical(
                f"Expected ON or OFF in response, received response: {response}"
            )
            raise BadDeviceStatus("Unexpected response from the device.")

    @property
    def _port_setting(self):
        return {
            DeviceStatus.OFF: self._GET_STATUS_OFF,
            DeviceStatus.ON: self._GET_STATUS_ON,
        }
